import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    The text is split into lines; each line is split at its first "=" into
    a name and a value, and both are stripped of surrounding whitespace.
    Lines without "=" are ignored. Key matching is exact and case-sensitive.
    If the key appears more than once, the first occurrence wins.
    Returns "" when the key is absent. A present key with an empty value
    also yields "". Values may themselves contain "=".
    """
    for raw in text.splitlines():
        name, sep, value = raw.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    text = "a=1\nb=2\nc=3"
    assert config_value(text, "a") == "1"
    assert config_value(text, "b") == "2"
    assert config_value(text, "c") == "3"


def test_missing_key_returns_empty_string() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_around_key_and_value_is_stripped() -> None:
    assert config_value("  name  =  value with spaces  \n", "name") == "value with spaces"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_empty_value_present_key() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_lines_without_equals_are_ignored() -> None:
    text = "garbage line\na=1\n\nnot a pair"
    assert config_value(text, "a") == "1"
    assert config_value(text, "garbage line") == ""


def test_first_duplicate_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_key_is_case_sensitive() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("Key=1", "Key") == "1"


def test_key_must_match_exactly_not_as_prefix_or_suffix() -> None:
    text = "abc=1\nab=2"
    assert config_value(text, "ab") == "2"
    assert config_value(text, "b") == ""


def test_value_is_not_matched_as_key() -> None:
    assert config_value("a=b\nb=c", "b") == "c"


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_trailing_newline() -> None:
    assert config_value("a=1\n", "a") == "1"


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("x=1", "x", "1"),
        ("x = 1", "x", "1"),
        ("=1", "", "1"),
        ("x=1", "", ""),
    ],
)
def test_parametrized(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected
